-- Resources guides that said "WUWF" or "Pensacola" where they only meant "the station". Content only; no schema.
-- The prefix continues the sequence past 20261105220000; see 20261103120000's header on why the prefix is a
-- sequence number, not a date.
--
-- A station that installs the Portal reads these guides, so a core tool guide should not name another
-- station. Five guides are reworded: a framing example in Editorial Planning's workflow, the DAD library
-- wording in the content library, the weather alert's place in Sources, the local-opportunity wording in
-- "Read a clock" (the legend now says "Local opportunity", and the guide matches it), and the editorial
-- requirements line in Sourcework's overview.
--
-- Deliberately not changed: the ten Bookings guides, whose wording mirrors labels on Bookings screens that
-- still say WUWF (they are neutralized together when Bookings is, and a station without Bookings never
-- sees them); log-dad-log, which names the DAD export's real file name; and
-- underwriting-migrate-legacy-copy, which documents WUWF's own one-off migration.
--
-- A guide an editor has changed since the last release is not overwritten: the helper flags it
-- needs_review and an editor reconciles. At WUWF that is log-content-library.

select private.rc_release_guide(
  p_slug => 'editorial-planning-workflow-overview',
  p_tool_key => 'editorial-planning',
  p_title => 'Editorial Planning: pitch to assignment',
  p_summary => 'Prepare pitches, score and document decisions.',
  p_screen_keys => array['editorial.backlog', 'editorial.meeting', 'editorial.pitch'],
  p_sort_order => 5,
  p_version_note => 'Station name removed so the guide reads for any station',
  p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Submit a useful pitch"}]},{"type":"paragraph","content":[{"type":"text","text":"A pitch should make a potential story legible to a colleague without requiring a separate conversation. State what is happening; whom it affects; why it matters now; what remains unknown; what evidence or sources might answer the question; and what reporting effort is likely required. Choose the coverage pillar that best describes the underlying public question, not merely the institution involved."}]},{"type":"paragraph","content":[{"type":"text","text":"Example:","marks":[{"type":"bold"}]},{"type":"text","text":" Rather than \"A university hosts a military program,\" frame the public question: whether a university's expansion of military-to-civilian training is changing access to civilian employment and for whom. The institutional activity is a lead to investigate, not necessarily the story's conclusion."}]},{"type":"paragraph","content":[{"type":"text","text":"The existing workflow permits a "},{"type":"text","text":"submitted pitch","marks":[{"type":"link","attrs":{"href":"/editorial"}}]},{"type":"text","text":" to be edited until it enters "},{"type":"text","text":"meeting scoring","marks":[{"type":"link","attrs":{"href":"/editorial/meetings"}}]},{"type":"text","text":"; use review history to understand whether it was assigned, deferred or archived."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Run a planning meeting"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors create the meeting and add eligible pitches to the slate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reviewers score independently against the published anchored criteria and record substantive concerns. An institutional alignment modifier must not substitute for the story's civic value, evidence or feasibility."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After scoring closes, consider the ranked agenda, disagreements and written comments. Scores inform editorial judgment; they do not make the assignment decision themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record the disposition and assignment clearly. A deferred pitch should have an understandable next step where possible; an assigned pitch should identify the responsible reporter."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conclude the meeting only after decisions are recorded. The concluded meeting is a permanent historical record."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"After assignment"}]},{"type":"paragraph","content":[{"type":"text","text":"The pipeline ends at the assignment. The pitch page records who is reporting the story and keeps every round's scores, comments and decision as the newsroom's record; the reporting itself is not tracked here."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Administration"}]},{"type":"paragraph","content":[{"type":"text","text":"Configuration guides should explain the difference between weighted core criteria and separate modifiers, how archived rubric elements preserve historical scores, and when changing criteria is justified. Any numerical example must match the live rubric."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct portal screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pitch backlog","marks":[{"type":"link","attrs":{"href":"/editorial"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meetings","marks":[{"type":"link","attrs":{"href":"/editorial/meetings"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Settings","marks":[{"type":"link","attrs":{"href":"/editorial/settings"}}]}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-content-library',
  p_tool_key => 'log',
  p_title => 'Building the content library',
  p_summary => 'Find, add, and approve news, promos, and other spots, or import the station''s existing DAD cut library in bulk.',
  p_screen_keys => array['log.library'],
  p_sort_order => 10,
  p_version_note => 'Station name removed so the guide reads for any station',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The content library holds everything a rundown can pull from — news, promos, membership messages, PSAs, legal IDs, and more. Anyone with On Air access can add to it, not just the program director."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find an item"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Type in the search box to search titles, DAD cart numbers, and scripts. The list updates as you type; pressing Enter searches straight away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clear the box to see the whole library again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the status chips (All, Approved, Draft, Retired) and the content type chips to narrow the list. Each status chip shows how many items it would show."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The library shows 25 items a page, newest first. The page links under the table move between pages."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a content item"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the library, select "},{"type":"text","text":"+ New content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a title, content type, summary, script, expected duration, and effective dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add its components"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the item's page, expand "},{"type":"text","text":"Add a component","marks":[{"type":"bold"}]},{"type":"text","text":" — choose a type (live intro, recorded audio, live outro, or an optional tag), a sequence, a duration, and a script. Select "},{"type":"text","text":"Add component","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A required component counts toward the item's total time; an optional one doesn't."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Approve it"}]},{"type":"paragraph","content":[{"type":"text","text":"An item starts as a draft. Set its status to Approved, in the Status panel on its page, before it can be picked for a rundown — only approved items are offered when filling a break."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import the station's DAD cut library"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the library, open the import screen and upload the Standard Library export from DAD (Library screen → Generate Reports → Standard Library) — optionally with its companion Groups report."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview import","marks":[{"type":"bold"}]},{"type":"text","text":" to see the plan: new items, updates to existing ones, and anything it couldn't place."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":" to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"There's no audio upload here. The station's playback system (ENCO/DAD) is where recorded material actually plays from — a content item is metadata and a script, not an audio file."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-running the import later updates an already-imported item in place (matched by its DAD cart number) instead of creating a duplicate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retiring stale content is an ordinary status change, not a delete — nothing in the library is ever removed outright."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-npr-and-weather',
  p_tool_key => 'log',
  p_title => 'Sources: NPR, weather and Florida News Exchange',
  p_summary => 'Check the outside feeds On Air reads: a program''s NPR stories, the current forecast, and stories shared by other Florida stations.',
  p_screen_keys => array['log.sources'],
  p_sort_order => 50,
  p_version_note => 'Station name removed so the guide reads for any station',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"Sources","type":"text","marks":[{"type":"link","attrs":{"href":"/log/sources"}}]},{"text":" tab holds the outside feeds On Air reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card's ","type":"text"},{"text":"Open","type":"text","marks":[{"type":"bold"}]},{"text":" button to go to that source's page, and ","type":"text"},{"text":"← Sources","type":"text","marks":[{"type":"bold"}]},{"text":" to come back.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What the cards say","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Up to date","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is inside its normal refresh window.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Stale","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is older than that, or the last refresh failed. What was saved is still shown.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not fetched yet","type":"text","marks":[{"type":"bold"}]},{"text":": nothing has been read from this source so far.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not configured","type":"text","marks":[{"type":"bold"}]},{"text":": the portal has no access set up for this source yet.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"NPR","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the NPR page, choose a program and a show date, then select ","type":"text"},{"text":"Switch","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The table lists each story's estimated air time (marked with “~”, since NPR doesn't supply exact times), title, teaser, and length.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Refresh","type":"text","marks":[{"type":"bold"}]},{"text":" to pull the latest episode data.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Weather","type":"text"}]},{"type":"paragraph","content":[{"type":"text","text":"The weather page shows the current forecast as a row of days, with the text for today and tonight under it. Select a day to read its forecast. Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" on the page or on the weather card to force an update."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weather alerts"}]},{"type":"paragraph","content":[{"type":"text","text":"When the National Weather Service has a warning, watch or statement active for the studio's area, a row appears under the forecast. It names the most severe alert and how many more there are. Select the row to see them all, select an alert to read it, and select "},{"type":"text","text":"Full NWS text","marks":[{"type":"bold"}]},{"type":"text","text":" for everything the Weather Service said."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Warnings come first, then watches, then statements."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The same row appears above "},{"type":"text","text":"Full forecast","marks":[{"type":"bold"}]},{"type":"text","text":" in a rundown's Weather panel and on a weather item's card."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alerts are checked every 15 minutes. If a check fails, the row shows the last alerts it had, with the time it last checked. If alerts have never been checked, the page says so instead of showing nothing."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Florida News Exchange"}]},{"type":"paragraph","content":[{"type":"text","text":"This page lists the stories other Florida stations shared through PRX in the last 24 hours, newest first. A wrap and its cut are listed together. Each version has a player (its menu has a download option), the feed description, and a link to its page on PRX."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The feed description is often only a summary. The full script can be on the story's PRX page: select "},{"type":"text","text":"Open on PRX","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A hold note from the feed, such as Hold until 10/8, appears beside the story. It is there for you to follow; the portal does not enforce it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Add to library","marks":[{"type":"bold"}]},{"type":"text","text":" to open the new content item form with the title, the type News, and a summary already filled in. The summary holds the description, any hold note and the PRX link. Paste the script, save, then add its components (live intro, recorded audio, outro) on the item's page, as for any library item."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audio is not copied into the portal. Load it into DAD to air it. The links in the feed expire after an hour, so if a player will not play, reload the page."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"NPR's estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to.","type":"text"}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-read-a-clock',
  p_tool_key => 'log',
  p_title => 'Read a clock',
  p_summary => 'The timeline and ring diagrams, hours of a longer shift, floating breaks, versions, and pinned content.',
  p_screen_keys => array['log.clock'],
  p_sort_order => 10,
  p_version_note => 'Station name removed so the guide reads for any station',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a clock from the program that airs on it: on the program's page, select "},{"type":"text","text":"Open clock","marks":[{"type":"bold"}]},{"type":"text","text":". The link at the top left of the clock's page goes back to that program."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Timeline and Ring"}]},{"type":"paragraph","content":[{"type":"text","text":"The diagram shows one hour of the clock. Switch between "},{"type":"text","text":"Timeline","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Ring","marks":[{"type":"bold"}]},{"type":"text","text":" at the top right of the diagram; both behave the same way."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The network's structure comes first: segments, newscasts (dark), and promos and credits. Local opportunities are marked in blue: a dashed outline for optional, solid for required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hover over or tab to a slot to read its name, times, and length. Select a slot to fix it in the side panel and the slot list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Slots list lists every slot. Hovering over a row highlights that slot in the diagram; selecting a row shows it in the side panel."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shifts longer than an hour"}]},{"type":"paragraph","content":[{"type":"text","text":"When a program airs for more than an hour, the clock repeats every hour. Use the arrows beside "},{"type":"text","text":"Hour 1 of 2","marks":[{"type":"bold"}]},{"type":"text","text":" to step through the hours. The network structure is the same in each hour, but pinned content can differ, and a small number on a local slot shows how many items are pinned for the hour you're looking at."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Floating breaks"}]},{"type":"paragraph","content":[{"type":"text","text":"A break whose position isn't fixed appears as a shaded window. A dashed edge can move and a solid edge is fixed; the darker area is always part of the break. Select it to see when it can start and end and how long it can run."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose a version from the "},{"type":"text","text":"Version","marks":[{"type":"bold"}]},{"type":"text","text":" menu. A version can't be edited once it exists — a correction is a new version, started with "},{"type":"text","text":"+ New version","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Changing what the station can fill (program director)"}]},{"type":"paragraph","content":[{"type":"text","text":"Select a slot, then use the buttons in its panel: "},{"type":"text","text":"Edit eligibility","marks":[{"type":"bold"}]},{"type":"text","text":" on a local slot, or "},{"type":"text","text":"Mark eligible for local content","marks":[{"type":"bold"}]},{"type":"text","text":" on a network-only one. "},{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" takes a slot out of local eligibility."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pinning content (program director or traffic)"}]},{"type":"paragraph","content":[{"type":"text","text":"A pin puts the same content item into a slot in every rundown made from this clock: the hourly station ID (see "},{"type":"text","text":"Station IDs","marks":[{"type":"bold"}]},{"type":"text","text":"), or a feature like BirdNote. Select a local slot, then "},{"type":"text","text":"Pin content","marks":[{"type":"bold"}]},{"type":"text","text":". Choose the item, then the hour and days. "},{"type":"text","text":"Every hour","marks":[{"type":"bold"}]},{"type":"text","text":" with no days checked covers the whole shift, every day. "},{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" under a pinned item takes the pin off."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-workflow-overview',
  p_tool_key => 'transcription',
  p_title => 'Sourcework: from recordings to reporting',
  p_summary => 'How the tool fits together: projects, sources, excerpts and pieces, and the optional analysis steps.',
  p_screen_keys => array['sourcework.projects', 'sourcework.project', 'sourcework.sources'],
  p_sort_order => 1,
  p_version_note => 'Station name removed so the guide reads for any station',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework takes recordings and documents from upload to a script. For an ordinary assignment you transcribe audio, pick your own actualities and write the piece by hand. The analysis steps, Analyze, Synthesis and Outline, are optional, and each one waits for your decision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start with the task you have"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For a complete first assignment, follow "},{"type":"text","text":"From interview recording to radio script","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-interview-to-script"}}]},{"type":"text","text":". It goes from uploading a recording through checking the transcript, saving excerpts and writing a piece, with no research questions and no AI."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To work on one step, see "},{"type":"text","text":"Starting a project and adding sources","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-starting-a-project"}}]},{"type":"text","text":", "},{"type":"text","text":"Working with the transcript and creating excerpts","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-transcript-and-excerpts"}}]},{"type":"text","text":" or "},{"type":"text","text":"Building a piece from narration and excerpts","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-pieces"}}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What each thing is"}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"source","marks":[{"type":"bold"}]},{"type":"text","text":" is an original recording or PDF. A "},{"type":"text","text":"transcript","marks":[{"type":"bold"}]},{"type":"text","text":" is derived text, and an "},{"type":"text","text":"excerpt","marks":[{"type":"bold"}]},{"type":"text","text":" is a stretch of a source saved for reuse: a time range of a recording, or a passage of a PDF. A "},{"type":"text","text":"project","marks":[{"type":"bold"}]},{"type":"text","text":" is the work for one story and refers to sources; the same source can be in more than one project without a second upload. A "},{"type":"text","text":"piece","marks":[{"type":"bold"}]},{"type":"text","text":" is a script built from narration and excerpts."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find and reuse what you already have"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Notebook","marks":[{"type":"link","attrs":{"href":"/sourcework?tab=notebook"}}]},{"type":"text","text":" on the Sourcework home lists every source and every excerpt, whichever project they are in, and its search box finds spoken words, passages and excerpts across all of them. See "},{"type":"text","text":"Browse the Notebook","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-browse-source-library"}}]},{"type":"text","text":" and "},{"type":"text","text":"Searching across projects and sources","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-search"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The optional steps, in order"}]},{"type":"paragraph","content":[{"type":"text","text":"A project's own Notebook tab shows where it stands and names the next step. "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" reads a source and proposes findings and a few clips, which you decide on from the project's "},{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" tab. "},{"type":"text","text":"Synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" reads the accepted findings and says what they establish for each research question. "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":" plans a piece as beats, and "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":" turns the beats into narration. See "},{"type":"text","text":"Analyzing a source","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-research"}}]},{"type":"text","text":", "},{"type":"text","text":"Synthesis","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-synthesis"}}]},{"type":"text","text":", "},{"type":"text","text":"Outline a piece","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-outline"}}]},{"type":"text","text":" and "},{"type":"text","text":"A project at a glance","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-project-overview"}}]},{"type":"text","text":". Each of these steps sends the project's material to an outside service; building by hand sends nothing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Check the underlying material"}]},{"type":"paragraph","content":[{"type":"text","text":"Before anything airs, verify quotations, speaker identities, names, numbers and the context of each excerpt against the original recording. Neither the transcript nor a finding replaces editorial judgment. Apply the station's editorial and confidentiality requirements when handling sources."}]}]}$body$
);
